import {q,t,lab} from './authoring.mjs';
const lifecycle=['Microsoft Windows lifecycle','https://learn.microsoft.com/en-us/lifecycle/products/windows-10-home-and-pro'];
const network=['Microsoft file sharing over a network','https://support.microsoft.com/en-us/windows/file-sharing-over-a-network-in-windows-b58704b2-f53a-4b82-7bc1-80f9994725bf'];
export default [
{key:'os-4',subject:'Operating Systems',slug:'dit-operating-systems',module:4,chapter:4,title:'Introduction to Windows 10',pages:'24-26',sources:[lifecycle,['Microsoft installation media','https://support.microsoft.com/en-us/windows/create-installation-media-for-windows-99a58364-8c02-206f-aa6f-40c3b507420d'],['Rufus project','https://rufus.ie/'],['Microsoft Windows help','https://support.microsoft.com/windows']],topics:[
t('4.1','Installation requirements and lab preparation',`The syllabus uses Windows 10. Windows 10 Home and Pro reached their normal end of support on 14 October 2025; special editions and eligible extended-update arrangements have separate conditions. This guide teaches the named syllabus environment in a controlled lab. Check the exact edition and current Microsoft lifecycle before choosing an everyday Internet-connected installation.

An installation needs compatible processor architecture, sufficient RAM and storage, supported drivers, installation media and an appropriate licence or authorised evaluation entitlement. The syllabus lab specification of a Core i3, 4 GB RAM and 250 GB disk is a teaching-lab baseline, not a universal statement of Microsoft\'s requirements for every edition or a promise of adequate performance for every workload.

Before changing a system, inventory its hardware and existing data, check the boot mode and target disk, obtain required drivers and verify a recoverable backup. A learner should use an instructor-assigned empty virtual disk or disposable training machine. The host computer and its personal files are outside the installation exercise. Record the intended edition, architecture, storage capacity and recovery plan in the lab sheet.`,[
q('What should an installation plan identify first?','The authorised target device, edition, requirements and recovery plan',['A random disk to erase','Only a wallpaper colour','A borrowed password to publish'],'Installation choices must match the authorised hardware and data-recovery requirements.'),
q('Is the syllabus hardware baseline a guarantee for every workload?','No, compatibility and workload requirements still need checking',['Yes, all software has identical demands','Yes, disk capacity determines every driver','No, because requirements never matter'],'A course baseline does not replace edition-specific and workload-specific checks.'),
q('Where should a learner practise partition-changing installation work?','An assigned disposable lab disk or VM',['The only copy of a family photo disk','An unrelated company server','Any visible drive without checking'],'Partition operations belong in an authorised lab with recoverable data.')]),
t('4.2','Bootable USB, optical media and Rufus',`Installation media contains boot files and setup data; copying an ISO file onto a USB as an ordinary document does not necessarily make the drive bootable. Obtain the OS image through an official authorised source and verify its intended edition and architecture. Use the vendor media-creation procedure or an appropriate tool such as Rufus according to the lab instructions.

For a Rufus-based exercise, connect only the assigned removable drive where possible, select that device by its actual capacity and identifier, select the approved image and choose the partition/boot settings that match the training machine. UEFI/GPT and legacy BIOS/MBR describe different boot arrangements; do not pick one merely because it appears first. Confirm the target before writing, because media creation can erase its contents.

For a DVD/CD workflow, the ISO must be written as an image to suitable media using an image-burning function rather than saved as an ordinary data file. Capacity matters: a particular image may not fit a CD. The firmware boot menu determines which device is attempted first. Distinguish preparing installation media from changing the installed system.`,[
q('Does copying an ISO as a normal USB file always make bootable installation media?','No, an appropriate media-preparation operation is needed',['Yes, the file name alone changes firmware','Yes, every USB is automatically bootable','No, because USB drives cannot hold files'],'Bootable media requires a suitable layout and boot files.'),
q('What must be checked immediately before writing an installation USB?','The exact target device and whether its data may be erased',['Only the colour of the USB casing','Whether every other disk can also be erased','The number of desktop shortcuts'],'Writing installation media can replace the selected device contents.'),
q('What should boot-mode and partition settings match?','The assigned firmware and installation design',['A random tutorial screenshot','The longest available menu label','The user account display picture'],'UEFI/legacy and partition choices must fit the lab target.')]),
t('4.3','A checked installation sequence',`A typical clean-installation lab follows this sequence: prepare and verify media; boot the assigned VM/device from it; select the required language and keyboard; identify the intended edition and licence path; choose the instructed installation type; select the assigned target storage; allow setup to copy files and restart; then complete the initial account and device settings. The exact screens depend on the image and edition.

The important checkpoint is before any disk-changing confirmation. Verify the target by more than its displayed order: use the lab inventory, capacity and assigned identity. If the expected disk or required driver is missing, stop the installation exercise and resolve the mismatch with the instructor. Do not delete another disk merely to make the example screen match.

After setup, verify the installed edition/version, computer name, device status, network configuration and update state. Reboot and sign in to the intended lab account. A desktop appearing once does not prove that storage, networking and recovery all work. Record the outcome and any unresolved driver or update requirement.`,[
q('Which checkpoint is essential before disk-changing setup actions?','Confirm the intended target against the lab inventory',['Choose the first listed disk automatically','Delete every visible partition','Ignore missing storage drivers'],'The selected disk must be the authorised lab target.'),
q('What should follow the first successful sign-in?','Verify devices, edition, network, updates and recovery requirements',['Assume all hardware is correct forever','Discard every backup immediately','Share the account password with the whole class'],'Post-installation verification checks actual system operation.'),
q('What should a missing expected disk prompt?','Investigation of the lab configuration or driver requirement',['Deletion of another unrelated disk','Repeated random formatting','A claim that installation is complete'],'Unexpected storage information must be resolved before proceeding.')]),
t('4.4','Partitions, formatting and storage verification',`A partition divides a disk\'s address space into defined regions. A volume is a storage area presented for use by a file system; a drive letter is one possible way Windows exposes a volume. The physical disk, its partitions, its file systems and its displayed letters are related but different concepts.

Formatting prepares a file system on the selected volume. It is not the same as creating a shortcut, defragmenting a drive or securely erasing every historical byte. A quick format is not a verified sanitisation procedure. An installation can also create supporting system/recovery partitions, so a learner should not remove unfamiliar partitions on a working personal computer.

Use Disk Management for observation before modification. In the authorised exercise, the instructor supplies an empty training disk and specifies the intended partition layout. Record capacity, file system and assigned label; create a harmless test file, reopen it and check the expected storage location. The procedure is complete only when the correct target and results have been verified.`,[
q('What is a partition?','A defined region of a disk address space',['The name of an email recipient','A permanently identical drive letter','A printer driver'],'Partitions describe storage regions, not application document names.'),
q('Does quick formatting prove secure destruction of all old data?','No',['Yes, every byte is always overwritten many times','Yes, it physically destroys the disk','No, because formatting never affects a file system'],'Formatting and validated data sanitisation are different operations.'),
q('Why distinguish a disk from a drive letter?','A disk can contain multiple volumes, and letters are logical access names',['Every disk must always be C:','A letter is the physical serial number','A drive letter proves an OS licence'],'Logical names do not uniquely describe physical storage.')]),
t('4.5-4.8','Desktop, Start, taskbar and Settings',`The desktop is the main graphical workspace. Icons represent items or shortcuts; a shortcut points to a target and is not an independent backup of the target file. The Start menu provides application and system entry points, while the taskbar shows launchers and running applications. Pinning an application makes access convenient; it does not necessarily install a second copy.

Settings groups many system preferences and configuration pages. Windows 10 also retains Control Panel for some tasks. A task can therefore have more than one entry point, and wording can vary by edition/update. Use the Start search to locate a named setting, then verify that the opened control matches the intended operation.

In the lab, create a shortcut to a harmless file, pin a permitted application and adjust a reversible desktop preference. Confirm that the original file still exists. Distinguish closing a window, minimising it and signing out. Signing out ends the user session and can close applications; it is not the same as locking the screen.`,[
q('What does a shortcut normally contain?','A reference to a target item',['A guaranteed independent backup of every target byte','A new processor','A replacement operating-system licence'],'A shortcut provides access to a target; it does not necessarily copy the target data.'),
q('What is the taskbar used for?','Launching and switching among applications',['Crimping a cable','Creating physical disk sectors','Replacing a file system'],'The taskbar is part of the graphical interaction environment.'),
q('How does locking differ from signing out?','Locking protects access to the existing session; signing out ends the user session',['They always have exactly the same effect on applications','Locking formats the disk','Signing out only changes brightness'],'Session termination and screen locking have different purposes.')]),
t('4.9-4.10','Drivers and application installation',`A driver supports communication between the OS and hardware. Graphics/VGA/SVGA/legacy AGP terminology in the syllabus describes display-device contexts; a current machine may use a different graphics connection or GPU architecture. Sound cards and wired/wireless NICs also need suitable driver support. Match the driver to the actual hardware and OS architecture rather than installing an unrelated package because its name sounds similar.

Check Device Manager for device identity and error indications. Prefer approved Windows update channels or the hardware manufacturer\'s verified support source. Record the current driver and recovery method before a lab update. After installation, test the specific function: display output, sound playback or network link. The presence of an installer completion message alone is insufficient.

Applications serve user tasks and are distinct from drivers. Obtain approved software, check compatibility/licensing and choose only needed components. Use Apps/Programs settings for a supported uninstall rather than deleting an arbitrary program folder. A typing tutor can be used to measure accuracy and speed with the same practice passage before and after training. Do not infer improved typing solely from a faster but error-filled attempt.`,[
q('What should a hardware driver match?','The actual device and supported OS/architecture',['Only the colour of the hardware','Any software with a similar file name','A favourite application name'],'Driver compatibility is specific to the device and operating environment.'),
q('Which tool helps inspect Windows device identity and problems?','Device Manager',['Slide Sorter','Mail Merge','A spreadsheet legend'],'Device Manager presents installed device information and status.'),
q('How should an approved application normally be removed?','Use its supported uninstall mechanism',['Delete random files from the system folder','Rename the Windows directory','Remove every hardware driver first'],'Supported uninstall procedures handle application components and registrations.'),
q('Which check is useful after a NIC driver installation?','Verify adapter status and the intended network connection',['Only change the wallpaper','Assume a completion dialog proves connectivity','Delete the assigned IP record'],'Functional verification checks the device\'s intended operation.')]),
t('4.11','Accounts, properties, roles and recovery',`A user account identifies a permitted user and holds settings and access relationships. A standard account is appropriate for routine student work; administrator privileges permit additional system changes and should be limited to tasks that require them. The displayed account name is not a reason to assume unrestricted authorisation.

In a disposable lab, create a clearly named training account using the supported account-management controls, assign the required role and test sign-in. Apply folder permissions to the intended identity, then test access as that user. Never publish real passwords in screenshots or lab reports.

For forgotten passwords, use the owner\'s official account recovery route or an authorised lab administrator\'s reset procedure. Recovery and reset are different from discovering the old password. A reset can affect access to encrypted data or saved credentials, so the lab must include the appropriate recovery keys and backup plan. Do not turn a password-recovery exercise into a bypass of another person\'s account.`,[
q('Which account type suits routine student work?','A standard user with necessary permissions',['A shared unrestricted administrator for every task','An account with a publicly posted password','An unrelated person\'s account'],'Routine work should use the privileges needed for its tasks.'),
q('What should be used for a forgotten personal account password?','The official owner recovery route or authorised reset procedure',['An attempt to bypass someone else\'s account','Publishing stored recovery codes','Deleting every account without a backup'],'Recovery must follow the owner\'s authorised process.'),
q('Does resetting a password necessarily reveal the previous password?','No',['Yes, the old password is always displayed','Yes, every reset recovers all encrypted files automatically','No, because accounts cannot be reset'],'A reset changes authentication information; it does not necessarily disclose the old secret.')]),
t('4.12-4.13','Tablet mode and virtual desktops',`Windows 10 tablet mode adapts parts of the interface for touch-oriented use on compatible devices. It is a user-interface mode, not a conversion of an ordinary display into touch-sensitive hardware. Availability and behaviour depend on the device and system edition/version.

Task View and virtual desktops organise windows into separate workspaces. For example, a learner can keep an assignment editor on one desktop and a browser used for study on another. They remain part of the same signed-in environment; creating a virtual desktop does not create a new virtual machine or independent OS installation.

Use Task View to create a second desktop, place harmless windows as instructed and switch between the workspaces. Check whether an application is still running before closing it. Distinguish this feature from a second physical monitor, remote desktop and dual-boot installation: these solve different problems.`,[
q('Does tablet mode add touch hardware to a non-touch display?','No',['Yes, software grows a new sensor','Yes, every monitor becomes a tablet','No, because touch devices cannot use Windows'],'Interface settings do not manufacture touch-sensitive hardware.'),
q('What is a Windows virtual desktop?','An organised workspace for windows within the signed-in environment',['A completely separate virtual machine automatically','A new physical monitor','A disk partition'],'Virtual desktops organise application windows; they are not independent installed systems.')]),
t('4.14-4.15','Connectivity, updates and protection',`A workgroup is a peer grouping for Windows network organisation; giving two computers the same workgroup name does not by itself guarantee shared-file access. Adapters, IP addressing, name resolution, discovery/profile settings, accounts, permissions and service rules also matter.

For DSL, the modem/router connects the local network to an ISP service through its supported DSL interface. Use the ISP\'s actual settings and credentials on an authorised training device. A Wi-Fi hotspot supplies a wireless local connection and may share another connection, such as cellular data. Neither seeing a Wi-Fi network name nor connecting to it proves that Internet access works.

Use Windows Update and approved vendor channels for applicable updates, and verify the resulting state. Windows Security provides protection/status controls such as Microsoft Defender and firewall configuration. A course lab should inspect protection settings and scan a harmless approved test folder, not disable protection to make an untrusted installer run. For a legacy syllabus OS, distinguish successful lab operation from current support eligibility.`,[
q('Does matching the workgroup name alone guarantee file sharing?','No, connectivity, identity, permissions and service settings also matter',['Yes, it overrides every permission','Yes, it assigns every host an address','No, because Windows cannot share files'],'Workgroup naming is only one part of the environment.'),
q('What does a Wi-Fi connection prove by itself?','A local wireless association, not necessarily working Internet access',['That every DNS lookup works','That the ISP account is paid','That every website is safe'],'Wireless association and end-to-end Internet service are separate checks.'),
q('Where should a DSL lab obtain ISP-specific settings?','From the authorised ISP/lab configuration',['From an unrelated classmate\'s password','From a random guess applied to a live router','From the display resolution'],'DSL service parameters are specific to the provider and authorised connection.')]),
t('4.16-4.18','Input settings, Urdu, printing and scanning',`Mouse and keyboard settings include preferences such as button behaviour, pointer movement and available input layouts. A keyboard layout determines how key presses map to characters; it is not the same as changing every document\'s proofing language or paragraph direction.

For Urdu typing in Windows 10, add the appropriate language/input keyboard in the system language controls, switch to that input layout and test a short phrase in a Unicode-capable editor. In Word, also choose appropriate right-to-left paragraph direction and a font that supports the script. This is preferable to assuming that an arbitrary third-party installer is required on every machine.

Install an approved printer or scanner with a compatible driver and the correct USB/network connection. Print one test page to the intended queue. For scanning, choose a suitable page size, colour mode, resolution and output format; preview, scan and reopen the saved result. Higher resolution increases file size and is not automatically necessary for every task. A paper jam or toner replacement must follow the particular device\'s powered-down/service instructions; do not pull apart powered equipment.`,[
q('Which combination is useful for Urdu document entry?','An Urdu input layout, Unicode-capable font and appropriate paragraph direction',['Only renaming the file .urdu','Only changing printer paper size','Only increasing the monitor refresh rate'],'Input, glyph support and text direction serve different parts of the task.'),
q('What should follow printer installation?','Print and inspect a test page from the intended queue',['Assume every queue points to the same device','Delete all other drivers automatically','Publish the administrator password'],'A test page checks the actual print path.'),
q('What should follow a scan?','Reopen the saved output and check readability, orientation and destination',['Assume every preview was saved automatically','Choose the largest possible file for every task','Delete the original before checking the output'],'Verification checks the saved result, not only the scanning dialog.')])
],short:[['Differentiate partition and formatting.','Partitioning defines storage regions. Formatting prepares a file system on a selected volume. Both require careful target identification; neither is merely a file rename.'],['Why is a backup needed before installation work?','Installation and partition changes can replace data or alter bootability. A verified recoverable backup protects the required data and recovery information.'],['What should be checked after installing a driver?','Confirm the correct device and driver status, then test the actual function such as sound, display output or connectivity.'],['How is a virtual desktop different from a VM?','A virtual desktop organises windows within an existing user environment. A VM provides a virtualised machine that can run an independent guest OS.'],['Why are keyboard layout and paragraph direction separate?','The layout maps keys to characters. Paragraph direction controls text flow and alignment for scripts such as Urdu. A supporting font is also required.'],['How should a scanning task be verified?','Open the saved file and check readability, pages, orientation, output format and the intended destination rather than relying only on the preview.']],long:[['Describe a controlled Windows installation lab.','Prepare an authorised image, compatible drivers, a suitable licence/evaluation path and a recoverable lab backup. Inventory the VM and assigned empty disk, choose matching firmware/media settings and verify the target before writing media or changing storage. Boot setup, select the instructed edition and options and install only to that lab target. After the first sign-in, check the installed system, device status, computer name, networking and updates; reboot and confirm repeatable access. Record the outcome and limitations. The exercise does not authorise modifying a learner\'s everyday disk.'],['Plan a student Windows workstation configuration.','Use a standard learner account and a separate authorised administration route. Set the appropriate keyboard and display preferences, install approved applications and compatible device drivers, and test each required function. Add Urdu input and right-to-left formatting where needed. Configure the intended lab network without assuming that a workgroup name alone grants access. Inspect protection and update status, create a sample document and verify print/scan workflows. Retain configuration notes and a recovery plan. Version-specific syllabus actions should be distinguished from current product-support decisions.'],['Explain a systematic peripheral troubleshooting method.','Identify the actual device and intended task, then check physical connection, power and the correct selected queue or input device. Inspect driver identity and status, use supported diagnostic controls and test with a small known example. For a printer, inspect the intended queue and a test page; for a scanner, inspect the saved image rather than only a preview. Change one relevant factor at a time and record the result. Use the manufacturer\'s instructions for paper jams and consumables; do not open powered equipment or install unrelated drivers.']],labs:[
lab('os4-hardware-firmware','Inventory and firmware observation',['Identify CPU, mouse, keyboard, monitor, RAM and storage in the assigned lab.','Record system information; inspect firmware date/time and boot order on an instructor-provided VM or screenshots.','Explain disk, USB and network boot entries without changing an everyday computer.'],'A labelled inventory and a correct explanation of boot priority.',{practicals:[1,2]}),
lab('os4-install','Prepare media and install a disposable guest',['Create an instructor-approved VM with an empty virtual disk and record its identity/capacity.','Prepare the assigned USB/image or attach the approved ISO to the VM; match the required boot mode.','Follow setup only on the assigned virtual storage; record the planned partition layout, computer name and lab account.','Reboot, sign in and verify the installed version and device status.'],'A functioning guest installation, storage record and post-install checklist.',{practicals:[3,4,5,6],environment:'Disposable instructor-authorised VM/device; this guide does not execute installation on the reader\'s machine.'}),
lab('os4-ui-apps','Personalise and maintain a lab workspace',['Change a reversible taskbar/desktop preference and create a shortcut to a sample file.','Inspect a permitted device driver through Device Manager and document both its settings-based and approved vendor-installer routes.','Install and remove an instructor-approved harmless application through supported controls.','On a compatible Windows 10 guest, inspect tablet mode and demonstrate Task View with two workspaces.'],'A workspace checklist and explanation of which operations change preferences, software or device support.',{practicals:[7,8,9,10,11]}),
lab('os4-connectivity','Check workgroup, DSL and hotspot concepts',['Record the guest adapter, intended lab workgroup and its addressing source.','Use an authorised spare training modem/router or instructor configuration sheet for the DSL settings; do not alter a live subscriber router.','Connect only to the assigned lab network/hotspot and separately test local link, gateway and name resolution.'],'A diagram and observations that distinguish local connection from Internet service.',{practicals:[12,13,14]}),
lab('os4-urdu-peripherals','Produce an Urdu document and scan evidence',['Add an authorised Urdu input layout and type a short phrase; use suitable font and paragraph direction in the editor.','Install the assigned printer using its approved driver and inspect a test page.','Configure a permitted shared printer as described in Module 5.','Install/select the lab scanner, scan a sample sheet and reopen the saved file.'],'A legible saved Urdu sample, one checked print page and one readable scan.',{practicals:[15,16,17,18,19]}),
lab('os4-accounts-recovery','Practise authorised recovery and protection',['Use a deliberately created disposable training account for an instructor-authorised reset, or document the official owner recovery path.','Explain the difference between password reset and recovering encrypted data; retain required keys for the lab.','Back up a sample folder, alter the disposable sample and restore it to a separate location; compare contents.','Inspect Windows Security and run an approved harmless-file scan without disabling protections.'],'A recovery plan, a verified restored sample and a recorded protection state.',{practicals:[23,24,25]})]
},
{key:'os-5',subject:'Operating Systems',slug:'dit-operating-systems',module:5,chapter:5,title:'Network Connectivity',pages:'25-26',sources:[network,['Microsoft ipconfig','https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/ipconfig'],['Microsoft ping','https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/ping']],topics:[
t('5.1','Workgroups and an authorised lab network',`A workgroup is a peer grouping used in a Windows network. Each computer can maintain its own local accounts; a workgroup is not an Active Directory domain. Matching the workgroup name can help organisation, but it does not create IP connectivity, a shared folder or permission to read another person\'s files.

Begin with an isolated instructor-approved LAN and an addressing plan. Give computers meaningful unique names, confirm their adapters and select the appropriate network profile for that trusted training environment. Record the workgroup name and restart if the particular system requests it. Keep an administrator recovery route for the lab.

Test the network in layers: physical/link connection, local IP configuration, peer reachability, name resolution, service availability and user permissions. One working layer does not prove every other layer. For example, a ping reply does not prove that a file-share account is authorised, and a visible computer name does not prove that its share is readable.`,[
q('What distinguishes a workgroup from an AD domain?','A workgroup normally uses peer/local account organisation rather than central domain membership',['A workgroup automatically makes every host a domain controller','A workgroup is the same as an IP subnet mask','A domain can never have central accounts'],'Workgroup naming and domain-based directory administration are different concepts.'),
q('What does a successful ping establish most directly?','An ICMP reachability result for that particular test',['Permission to read every shared folder','Proof that a printer is installed','Proof that all DNS names resolve'],'Application services and permissions need separate checks.'),
q('What is the first step in a safe sharing exercise?','Use an authorised isolated lab and an addressing/access plan',['Share a personal home directory publicly','Disable every firewall permanently','Guess another user\'s password'],'The network and data must be appropriate to the lab task.')]),
t('5.2','Host addressing and subnet checks',`An IPv4 host configuration includes an address and subnet mask/prefix, and often a default gateway and DNS server. The address identifies the host interface in its IP context. The prefix identifies which destination addresses are treated as on-link. The gateway is used for destinations outside the local subnet when a matching route is unavailable. DNS resolves names; it is not a substitute for a gateway.

For a simple isolated example, PC-A is 192.168.50.10/24 and PC-B is 192.168.50.11/24. Both belong to network 192.168.50.0/24; 192.168.50.255 is that subnet\'s broadcast address. A router interface at 192.168.50.1 can be the gateway when it actually connects to the required other networks. Do not enter a made-up gateway simply because an example uses .1.

Use either the authorised DHCP configuration or documented static settings, avoiding duplicate addresses and the network/broadcast addresses for ordinary hosts. Record the configuration with ipconfig /all. Test the actual assigned local address, a permitted peer and the intended gateway. A failed ping may involve policy or ICMP filtering; it is not proof of one particular fault.`,[
q('What determines whether a destination is in the local IPv4 subnet?','The address together with the subnet prefix/mask',['Only the computer name','Only the default browser','Only the last decimal digit'],'The prefix identifies the network portion used for the on-link decision.'),
q('Which is an ordinary host address in 192.168.50.0/24?','192.168.50.10',['192.168.50.0','192.168.50.255','300.168.50.10'],'The .0 network and .255 broadcast addresses are not ordinary hosts in this /24.'),
q('What is a default gateway used for?','Forwarding traffic toward destinations outside the local subnet when the route requires it',['Replacing all DNS records','Changing the keyboard layout','Naming a shared printer'],'The gateway must be a reachable router that provides the intended forwarding path.'),
q('Why avoid duplicate static host addresses?','They can create address conflicts and unreliable communication',['They make every network faster','They replace the need for a subnet mask','They guarantee free Internet service'],'Each ordinary active host interface needs an appropriate non-conflicting address in the lab.'),
q('Which command shows detailed Windows adapter configuration?','ipconfig /all',['slides /sort','format /presentation','word /table'],'ipconfig /all reports detailed adapter configuration.')]),
t('5.3','File sharing and effective permissions',`Create a dedicated training folder with a harmless sample file. Share that folder only with the intended lab identities. In Windows, access through a share can depend on both share permissions and underlying file-system permissions, as well as identity, service availability and network policy. A permissive setting in one place does not erase a restriction in another.

A UNC path such as \\LAB-A\Assignments identifies a server/share path. When troubleshooting, compare access by the intended name and, where permitted, the address. If address-based access works but name-based access fails, investigate name resolution rather than immediately replacing the cable. If the service is reachable but access is denied, inspect the actual account and permissions.

Test from a separate learner account, not only from the administrator who created the share. Demonstrate the required read, create or modify operation and also a prohibited operation using disposable data. Keep passwords and private paths out of public screenshots. Remove or restore the training share according to the lab plan after assessment.`,[
q('Why should a shared folder be tested as the learner?','Administrator access does not prove that the learner has the intended permissions',['All accounts always have identical permissions','A shared folder has no access rules','A folder name authenticates every user'],'Effective access must be tested with the actual intended identity.'),
q('What can affect access to a Windows shared file?','Both share and file-system permissions, identity and service settings',['Only the icon colour','Only the monitor size','Only the number of folder letters'],'Network access depends on several coordinated controls.'),
q('If a share works by address but not by name, what should be investigated?','Name resolution',['Printer paper alignment only','Keyboard repeat delay only','The document font only'],'A naming failure can remain even when the underlying network path works.'),
q('What should a training share contain?','Dedicated harmless lab files',['The only copy of private client documents','A public list of real passwords','Every personal folder by default'],'Use data and permissions appropriate to the authorised exercise.')]),
t('5.4','Printer sharing',`A shared printer lets authorised clients send jobs to an exposed print queue. The device must be installed and functional at the host or print server before client sharing is assessed. Identify the intended printer and connection, apply supported drivers and share the queue with the required lab identities.

On a client, add the designated shared queue through supported printer controls or the instructed network path. Driver compatibility and permissions still matter. Print a labelled one-page test from that client and confirm which physical device produced it. A visible queue icon does not prove that paper was printed at the correct location.

Troubleshoot host/device readiness, queue state, connectivity, identity and driver compatibility separately. Avoid solving one queue error by granting everyone unrestricted administration. The demonstration is complete when the authorised client can perform the assigned print operation and the result is inspected.`,[
q('What should be verified before sharing a printer?','The host can use the correct installed printer successfully',['Every learner is an administrator','The queue icon has a favourite colour','The paper tray is removed'],'The underlying host/device print path must work first.'),
q('What is a useful client-side sharing test?','Print a labelled page and inspect it at the intended device',['Only view the queue icon','Assume the host test proves every client works','Change all user passwords'],'The test verifies client permissions, queue selection and actual output.'),
q('Does sharing a queue automatically provide compatible drivers to every client?','No, client compatibility and configuration still need checking',['Yes, every driver works on every platform','Yes, a queue name changes CPU architecture','No, because printers never use drivers'],'Shared access does not eliminate platform and driver requirements.')]),
t('5.5-5.6','Permissions, demonstration and troubleshooting evidence',`Build a short acceptance table before the demonstration. For example: learner A can read the template, create a submission in the assigned folder and print one test page; learner A cannot edit the instructor\'s master file. Record the permitted identity and expected result for each operation.

Capture evidence in a useful order: network diagram, addressing table, adapter configuration, peer test, share path, permission settings and the actual file/print result. Redact secrets. A successful authorised transfer should preserve the sample file\'s expected contents. Reopen the copied file rather than assuming a progress bar proves correctness.

When a task fails, write the observed symptom before changing anything. Link down suggests a different starting point from 'access denied'. Compare expected and observed configuration, change one justified setting, repeat the original test and record the outcome. Restore temporary shares, accounts and configuration to the approved lab baseline after the exercise.`,[
q('Which evidence best confirms a shared-file copy?','Open the copied sample and compare its expected contents',['Only show a network icon','Only state that a progress bar appeared','Only count the characters in the share name'],'Verification must inspect the actual transferred result.'),
q('What is the purpose of an acceptance table?','Define identities, permitted operations and expected results before testing',['Replace every network setting','Guarantee no hardware can fail','Avoid observing actual outcomes'],'Expected results make the demonstration assessable.'),
q('Which response to an access-denied error is appropriate?','Check the identity and effective permissions for the requested operation',['Erase every drive','Disable all security controls permanently','Assume the cable must be physically broken'],'An authorisation symptom should prompt relevant access checks.'),
q('What should follow a temporary lab sharing exercise?','Restore the approved baseline and remove unneeded training access',['Leave every training account publicly privileged','Publish all credentials with the report','Delete unrelated user documents'],'Lab cleanup should follow the authorised configuration plan.'),
q('Why change one justified setting at a time?','It helps associate the observed result with a particular change',['It guarantees the first guess is right','It makes documentation unnecessary','It replaces the need for an original symptom'],'Controlled troubleshooting produces clearer evidence.')])
],short:[['What is a workgroup?','A peer grouping for Windows computers, normally with local account management. It is not the same as central Active Directory domain membership.'],['What must match for two simple same-LAN hosts?','Appropriate unique addresses, compatible prefix/mask and a working link. A remote destination additionally requires suitable routing; services and permissions are separate.'],['Why distinguish DNS and gateway?','DNS resolves names to records such as addresses. A gateway forwards traffic toward other networks. Either can fail independently.'],['Why can a ping reply coexist with access denied?','ICMP reachability and file-service authorisation are different checks. The actual user still needs the required share/file permissions.'],['What should a printer-sharing test include?','A known working host printer, correct shared queue, compatible client setup, the intended user and an inspected client test page.'],['What makes a troubleshooting report useful?','It records expected and observed behaviour, addresses, names, identities, relevant settings, one justified change and the repeated test result.']],long:[['Design a two-computer sharing demonstration.','Use an isolated lab LAN with two permitted computers and a documented address plan, such as .10 and .11 in the same /24. Verify link and adapter settings, then test peer reachability. Create a dedicated sample share with the intended learner permissions, and access it from the other computer using that identity. Copy a harmless file and reopen the result. Separately test a prohibited modification to the master template. Document the share path and results, redact secrets and restore the approved baseline afterward.'],['Explain how to diagnose a failed share.','Begin with the actual symptom. Check physical link and addressing before higher-layer assumptions. Test a permitted peer and gateway, then compare access by name and address to assess resolution. If the service responds but access is denied, inspect the user identity and the effective share/file permissions. Check relevant service and firewall/profile configuration rather than disabling all protection. Make one justified change and repeat the original operation with the learner account. Record both successes and remaining failures.'],['Explain least privilege for shared files and printers.','The instructor\'s master files and administrative settings need stronger protection than a learner submission folder. Assign explicit permitted operations and identities. Allow the learner to read a template, create the required submission and use the designated print queue without giving broad system administration. Test as the learner and inspect the actual copied or printed output. Keep recovery access under authorised administration, and remove temporary permissions when the exercise ends. Least privilege supports a functioning workflow while limiting unnecessary access.']],labs:[lab('os5-ip-share','Address and share on two lab computers',['Record an approved static or DHCP plan; for a static exercise use unique hosts in the assigned subnet.','Set only the assigned lab adapter configuration and record ipconfig /all.','Create a dedicated sample folder, assign the specified share/file permissions and test from the second computer as the learner.','Copy and reopen the sample; compare permitted and prohibited operations.'],'Correct addressing and a verified transfer with the intended permissions.',{practicals:[20,21,22],covers:['5.1','5.2','5.3','5.5','5.6']}),lab('os5-shared-printer','Verify a shared print queue',['Confirm a local host test page first.','Share only the assigned queue; add it on the authorised client using compatible drivers.','Print one identified page from the client and inspect the intended device output.'],'A successful permitted client print and recorded queue identity.',{practicals:[17],covers:['5.4']}),lab('os5-fault-table','Diagnose three fictional failures',['For link-down, name-lookup failure and access-denied symptoms, select different initial checks.','Write the evidence that would confirm or reject each hypothesis.','Explain why a successful ping alone does not prove file-sharing permissions.'],'A symptom-to-test table without random configuration changes.')]
},
{key:'os-6',subject:'Operating Systems',slug:'dit-operating-systems',module:6,chapter:6,title:'Windows Server 2019/2016',pages:'25-26',sources:[['Microsoft Windows Server documentation','https://learn.microsoft.com/en-us/windows-server/'],['AD DS overview','https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/virtual-dc/active-directory-domain-services-overview'],['DHCP overview','https://learn.microsoft.com/en-us/windows-server/networking/technologies/dhcp/dhcp-top'],['DNS overview','https://learn.microsoft.com/en-us/windows-server/networking/dns/dns-overview'],['WINS overview','https://learn.microsoft.com/en-us/windows-server/networking/technologies/wins/wins-top']],topics:[
t('6.1-6.2','Server purpose, clients and a controlled installation',`A server provides services to clients. Windows Server is a server operating-system family that can host roles such as directory, name resolution, address configuration and printing. 'Client' and 'server' describe roles in an interaction; a machine\'s appearance or screen size does not determine its role.

The syllabus names Windows Server 2019/2016. Use an authorised installation image and a disposable lab or instructor-provided VM, and check the exact edition\'s requirements, licensing and lifecycle before deployment decisions. The lab can compare a server with a Windows client without assuming that every desktop OS has the same server role features.

A basic server-installation record includes the assigned VM, empty virtual disk, image/edition, intended computer name, network plan and recovery snapshot. Install only in that lab, configure the intended identity and connectivity, apply applicable updates and verify sign-in and device state. Roles are added for a purpose; installing every available role is not a substitute for a design.

Server administration should use appropriate accounts, change records and backups. A training domain, DHCP server or DNS service must remain on the isolated lab network so that it cannot interfere with real users.`,[
q('What defines a server in a client-server interaction?','It provides a requested service to clients',['It must have the largest monitor','It must be a laptop','It cannot also use another service'],'Client and server describe service relationships.'),
q('What is a Windows Server role?','A set of components for a defined service function',['Only the colour of a desktop theme','A guarantee that every service should be enabled','The number of physical keys on a keyboard'],'Roles organise services such as directory, DNS, DHCP and printing.'),
q('Where should a training server with DHCP or directory roles run?','An isolated authorised lab network',['An uncontrolled live office LAN','Any public Wi-Fi without permission','A network chosen at random'],'Lab services must not interfere with real clients.'),
q('What should guide selection of installed roles?','The specified service requirements',['Install every role regardless of need','Only the disk label','The student\'s favourite icon'],'A service design determines the necessary roles and configuration.')]),
t('6.3.1','Print and Document Services',`Print services centralise the exposure and administration of printer queues. The administrator associates a queue with the intended device, approved drivers and access rules. Clients connect to the published queue and submit jobs according to their permissions.

For a lab, first verify that the server can print to the designated device. Create or expose the required queue, configure learner access and connect an authorised client. Inspect a labelled client test page. Queue status, device readiness, driver compatibility and identity are different troubleshooting concerns.

Document-related services and print-management options vary by installed server version and role services. Teach the required queue workflow and use the actual Server Manager/management tools available in the lab rather than promising every optional service in every edition.`,[
q('What is a practical purpose of central print services?','Manage shared printer queues and authorised client use',['Turn every document into a domain account','Replace all network addressing','Remove the need for printer readiness'],'Central administration manages queues, devices and access.'),
q('Which output verifies an authorised client print path?','A labelled page produced by the intended physical printer',['Only a server-role icon','Only an unused driver file','Only a changed computer name'],'The actual result verifies the end-to-end task.')]),
t('6.3.2','Active Directory Domain Services',`Active Directory Domain Services stores and organises directory information about objects such as users, groups and computers. A domain controller hosts the directory service for its domain. Central directory administration can support authentication and access-policy management across joined computers; it is not the same as a peer workgroup name.

In a lab design, choose an instructor-approved namespace, a stable server addressing plan and appropriate DNS configuration. Add the AD DS role using the supported Server Manager workflow, then follow the promotion process to create or join the intended training domain. Record the directory-recovery plan and credentials securely. The exact wizard screens depend on the lab version.

Create only training users and groups, assign a limited test policy and join an authorised client using an account permitted to do so. Verify name resolution and a learner domain sign-in. A domain join or visible directory object alone does not prove that every intended permission or policy has been applied. Compare the actual authorised operation against the lab acceptance table.`,[
q('What does AD DS organise?','Directory objects such as users, groups and computers',['Only image pixels','Only spreadsheet chart colours','Only printer paper sizes'],'AD DS stores and makes directory information available through controlled services.'),
q('What is a domain controller?','A server hosting the domain directory service',['Any cable attached to a switch','A browser home page','A renamed workgroup on every desktop'],'A domain controller has a directory-service role.'),
q('Why does a domain lab need working DNS?','Clients must locate the domain and its services through appropriate name records',['DNS replaces all user permissions','DNS changes every account password','DNS is the same as a print queue'],'Correct name resolution is important to directory-service discovery.'),
q('Does joining a domain prove that all application permissions are correct?','No, the intended operations and policies still need testing',['Yes, it grants every user unrestricted access','Yes, every folder becomes public','No, because domains have no users'],'Membership and specific effective access are separate matters.')]),
t('6.3.3','DHCP service',`DHCP supplies leased network configuration to clients. A scope describes an address pool and related settings for a network. Exclusions keep selected addresses out of general assignment; a reservation associates an intended client identity with a particular lease assignment under the configured system. A lease has a lifetime and must be managed or renewed according to the protocol.

A common introductory exchange is Discover, Offer, Request and Acknowledge. This is a teaching view of an initial acquisition; renewal and exceptional cases have additional behaviour. A DHCP server can also provide options such as a default gateway and DNS server addresses. It does not automatically create correct routing or DNS records for every scenario.

In the isolated Windows Server lab, install the DHCP role, follow required domain-authorisation/post-install steps where applicable, create the assigned scope, set exclusions and options, activate it and configure a client for automatic addressing. Inspect the actual lease and client configuration. Never enable a learner DHCP server on a live school or office LAN without its administrator\'s authorisation.`,[
q('What is the main purpose of DHCP?','Lease network configuration to clients',['Resolve every domain name by itself','Print all user passwords','Convert every switch into a router'],'DHCP automates address and option configuration.'),
q('What does a DHCP exclusion do?','Keeps selected addresses out of general pool assignment',['Publishes those addresses as public passwords','Converts an address into a domain name','Guarantees the router is connected'],'Exclusions protect addresses intended for other controlled use.'),
q('Which sequence describes a common initial DHCP exchange?','Discover, Offer, Request, Acknowledge',['Print, Save, Format, Exit','Read, Write, Rename, Delete','Query, Slide, Chart, Merge'],'The DORA sequence is the common introductory acquisition model.'),
q('What should be checked after a DHCP lab client connects?','Its actual lease, address, prefix, gateway and DNS options',['Only the server wallpaper','Only the client font size','Only the queue name'],'The received configuration must match the intended scope and options.')]),
t('6.3.4','DNS service',`DNS is a distributed naming system. An A record associates a name with an IPv4 address; an AAAA record associates a name with an IPv6 address. A zone contains administratively managed DNS information. A reverse lookup uses the appropriate reverse namespace and records to look up a name associated with an address.

In an isolated lab, configure the DNS role and the assigned zone/records according to the instructor\'s design. Point the client at the intended resolver, then test a deliberately created training name such as a name under the reserved example.test namespace. Compare a name lookup with an address-based reachability test. A cached answer can persist according to its TTL, so an immediate repeat does not necessarily query the authoritative server again.

DNS and DHCP cooperate but have different responsibilities. DNS returns name-related records; DHCP provides leased configuration. A computer can have a valid static address and broken DNS, or valid DNS settings and no route to a remote service. Diagnose the actual layer and inspect the configured resolver rather than treating every network failure as the same problem.`,[
q('Which DNS record maps a name to an IPv4 address?','A',['AAAA only','A printer queue entry','A DHCP exclusion'],'A records contain IPv4 address information.'),
q('Which DNS record contains an IPv6 address?','AAAA',['An Excel cell style','A Windows workgroup label','An MBR partition entry'],'AAAA records contain IPv6 address information.'),
q('Does successful DNS resolution prove that an application service is reachable?','No, routing, policy and the service can still fail',['Yes, a name record guarantees every TCP port','Yes, DNS removes all firewalls','No, because names cannot map to addresses'],'Name resolution and application reachability are separate checks.'),
q('What can affect whether a repeated query reaches a server again immediately?','DNS caching and record TTL',['Only the monitor size','Only the desktop wallpaper','Only the file extension of an essay'],'A resolver can use a cached result within its applicable lifetime.')]),
t('6.3.5','WINS and service comparison',`WINS is a legacy name service associated with NetBIOS name resolution. It is not the modern general replacement for DNS, and an instructor should not require it for every new network merely because it appears in an older syllabus. Learn its historical purpose and recognise situations in which legacy applications may refer to it.

Compare services by the problem they solve: AD DS organises directory objects and domain services; DHCP leases network configuration; DNS resolves DNS names and other records; WINS supports legacy NetBIOS naming; print services expose and administer print queues. A single lab server may host more than one role, but that does not make the protocols interchangeable.

For assessment, explain each role, draw its client interaction and state one verification method. For a directory service, test authorised domain sign-in; for DHCP, inspect a lease; for DNS, query a known training record; for printing, inspect a client test page. WINS can be assessed through a documented legacy scenario rather than adding an unnecessary service to an everyday network.`,[
q('What is WINS primarily associated with?','Legacy NetBIOS name resolution',['Rendering every modern webpage','Replacing all DHCP leases','Formatting an SSD'],'WINS addresses a legacy naming context.'),
q('Which comparison is correct?','DHCP supplies configuration while DNS answers DNS name-record queries',['DHCP and DNS are identical operations','AD DS is only a printer driver','WINS is a spreadsheet function'],'The services have distinct responsibilities.'),
q('Should WINS be installed on every new network just because it appears in the syllabus?','No, assess an actual legacy requirement',['Yes, it is required for every modern DNS lookup','Yes, it replaces all access controls','No, because historical concepts cannot be studied'],'Learning a legacy function does not justify an unnecessary production role.'),
q('Which test matches a DNS role?','Query a known training name and compare the expected record',['Only print a blank sheet','Only rename the case of a folder','Only count USB ports'],'A DNS test should inspect a name-resolution result.')])
],short:[['Differentiate client and server.','A client requests a service; a server provides it. The roles describe an interaction, and a machine may serve one task while acting as a client for another.'],['What is a server role?','An installed/configured service function such as AD DS, DHCP, DNS or printing, selected to meet a defined network requirement.'],['What is a DHCP scope?','A configured address pool for a network with relevant exclusions, lease settings and options such as gateway/DNS configuration.'],['Why does AD DS depend on correct name resolution?','Clients must locate domain services and domain controllers through appropriate DNS information. Incorrect DNS can prevent expected discovery or sign-in operations.'],['Compare A and AAAA records.','An A record contains an IPv4 address; an AAAA record contains an IPv6 address. Both are DNS record types.'],['What is the place of WINS in the syllabus?','It is a legacy NetBIOS naming service. Students should understand the historical use without assuming it is required for every modern deployment.']],long:[['Plan an isolated Windows Server lab.','Use an instructor-approved VM, image, licence/evaluation arrangement, empty virtual disk and recovery snapshot. Record the computer name and addressing plan, install the assigned server edition and verify its update/device state. Select only required roles. Keep DHCP, DNS and directory exercises on an isolated virtual network, use training identities and retain recovery information securely. Define acceptance tests before making changes: a lease, a known name lookup, an authorised domain sign-in and a labelled client print where those roles are included.'],['Compare AD DS, DHCP, DNS, WINS and printing.','AD DS manages directory objects and domain-related services. DHCP leases addresses and configuration options. DNS returns records for DNS names and related namespaces, including A and AAAA address records. WINS serves legacy NetBIOS name resolution. Print services manage shared print queues. A server may host several roles, but each needs the correct configuration and verification. A successful DHCP lease does not prove a directory policy is correct, and a successful DNS query does not prove a printer has produced paper.'],['Explain a DHCP/DNS client acceptance test.','Create the assigned isolated DHCP scope with exclusions and options, and configure a test client for automatic addressing. Inspect the received address, prefix, gateway, DNS servers and corresponding server lease. Separately create or identify an authorised training DNS record and query it through the intended resolver. Compare the result with the expected address and test reachability as a separate operation. Record cache/TTL considerations when changing a record. Investigate the actual failing layer instead of enabling every server role or disabling all policy controls.']],labs:[lab('os6-server-install','Install an authorised training server',['Create the assigned isolated VM and record its image, edition, empty disk and recovery snapshot.','Complete installation only in that guest, set its intended name/addressing and verify sign-in and applicable updates.','Record which roles are required for the following tests.'],'An operational training guest with a documented baseline.',{practicals:['Additional a']}),lab('os6-ad','Demonstrate a training directory domain',['Use the instructor-approved namespace, stable server address and DNS design.','Install AD DS and complete the required promotion workflow with securely retained recovery information.','Create training identities, join an authorised test client and verify learner sign-in plus one permitted operation.'],'An isolated domain demonstration with a checked identity and access outcome.',{practicals:['Additional b']}),lab('os6-dns','Demonstrate a DNS record',['Install/configure the role only in the isolated lab and use the assigned zone.','Add a known training A record, configure the client resolver and query the name.','Change a disposable record as instructed and explain any cached answer/TTL.'],'Recorded expected and observed DNS answers.',{practicals:['Additional c']}),lab('os6-dhcp','Demonstrate a DHCP lease',['Add the DHCP role and required post-install/domain-authorisation settings for the assigned lab.','Create the isolated scope, exclusions, lease settings and intended gateway/DNS options; activate the scope.','Request automatic configuration from a lab client and inspect both client settings and server lease.'],'A lease consistent with the assigned scope and options.',{practicals:['Additional d']})]
}
];
